import * as k from '../anatomy/iso-kit.mjs';
export function atlas(kind){const P=k.fitProjection(k.boxCorners({x:-80,y:-50,w:160,d:100,r:2},-8,110),420,260,{pad:20,azimuth:35,elevation:30});const S=(x,y,w,d,z,h,tone='mid')=>k.solidSvg(k.slabOf({x,y,w,d,r:Math.min(1,w/4)},z,h,P,3,.4),{tone});let out='';for(const x of [-70,70])for(const y of [-40,40])out+=S(x-4,y-4,8,8,-8,5,'lo');out+=S(-80,-50,160,100,-3,3,'lo');for(const x of [-72,72])for(const y of [-42,42])out+=S(x-2,y-2,4,4,0,1,'hi');if(kind==='engine'){out+=S(-30,-20,60,45,0,8);out+=S(-30,-20,60,5,8,80);for(let i=0;i<8;i++)out+=S(-34,-23,68,4,18+i*8,2,'lo');out+=S(-18,-8,36,28,55,18,'hi');out+=S(-4,0,8,8,15,40);out+=S(-32,-20,64,45,88,7);for(const x of [-15,15]){out+=S(x-2,0,4,4,95,13,'hi');for(let i=0;i<5;i++)out+=S(x-4,-2,8,8,96+i*2,1,'lo')}}else if(kind==='hydraulic'){for(const [x,w,z]of [[-45,24,65],[35,45,45]]){out+=S(x-w/2,-20,w,40,0,5);out+=S(x-w/2,-20,w,4,5,70);out+=S(x-w/2,-16,4,32,5,70);out+=S(x+w/2-4,-16,4,32,5,70);out+=S(x-w/2+4,-16,w-8,32,5,z-5,'lo');out+=S(x-w/2+4,-16,w-8,32,z,4,'hi');out+=S(x-3,-3,6,6,z+4,25,'hi');out+=S(x-w/2,-20,w,40,z+29,4);for(let j=0;j<8;j++)out+=S(x-w/2-4,-20,3,4,8+j*8,1,'hi')}}else{out+=S(-60,-30,120,60,0,7);for(const y of [-22,22])out+=S(-54,y,108,6,7,50);for(let i=0;i<14;i++)out+=S(-50+i*7,-29,2,58,57,3,'lo');out+=S(-56,-10,112,20,25,20,'hi');out+=S(-72,-4,145,8,31,8,'hi');for(const x of [-55,55]){out+=S(x-4,-27,8,54,8,50);for(const y of [-22,22])out+=S(x-2,y-2,4,4,58,2,'hi')}out+=S(-15,-12,30,24,60,12);for(const x of [-8,0,8])for(const y of [-5,5])out+=S(x-1,y-1,2,2,72,3,'hi')};return k.figureSvg({width:420,height:260,label:'Ficha isométrica del ensamblaje construida con Anatomy',body:[out]});}
